var variables = lang.Docs{
	"$ENV":     {Signature: "$ENV", Summary: "Object of the environment variables when jq started."},
	"$__loc__": {Signature: "$__loc__", Summary: "Object with the `file` and `line` of this location in the program."},
	"$ARGS":    {Signature: "$ARGS", Summary: "Object of the arguments given with `--arg`, `--argjson` and friends (`named`) and after `--args` or `--jsonargs` (`positional`)."},
}

func Doc(name string, tok lang.Token) (lang.Doc, bool) {
	table := functions
	switch {
	case tok.Kind == lang.Variable:
		table = variables
	case name != "" && name[0] == '@':
		table = formats
	}
	doc, ok := table[name]
	return doc, ok
}
